const API_KEY = 'twelvedata_key';

const tickers = [
  'NVDA', 'MSFT', 'GOOGL', 'META', 'AMZN', 'AVGO',
  'AMD', 'TSM', 'ASML', 'PLTR', 'SMCI', 'TSLA'
];

return tickers.map(ticker => ({
  json: {
    ticker,
    url: `https://api.twelvedata.com/time_series?symbol=${ticker}&interval=1day&outputsize=300&apikey=${API_KEY}`
  }
}));

const runDate = new Date().toLocaleDateString('en-CA', {
  timeZone: 'Asia/Singapore'
});

const ticker =
  $json.meta?.symbol ||
  $json.ticker ||
  'UNKNOWN';

const values = $json.values;

if (!Array.isArray(values) || values.length < 30) {
  return [];
}

const ordered = [...values].reverse();

const closes = ordered
  .map(v => Number(v.close))
  .filter(v => Number.isFinite(v));

if (closes.length < 30) return [];

const pct = (a, b) => {
  if (!Number.isFinite(a) || !Number.isFinite(b) || b === 0) return null;
  return ((a / b) - 1) * 100;
};

const avg = arr => {
  const nums = arr.filter(v => Number.isFinite(v));
  return nums.length ? nums.reduce((a, b) => a + b, 0) / nums.length : null;
};

const round = x => Number.isFinite(x) ? Number(x.toFixed(4)) : null;

const latest = closes.at(-1);
const previous = closes.at(-2);
const close20 = closes.at(-21);
const ma50 = avg(closes.slice(-50));
const ma200 = avg(closes.slice(-200));
const high52 = Math.max(...closes.slice(-252));

return [
  { json: { run_date_sgt: runDate, ticker, metric: 'close', value: round(latest), source: 'twelve_data' } },
  { json: { run_date_sgt: runDate, ticker, metric: 'change_pct', value: round(pct(latest, previous)), source: 'twelve_data' } },
  { json: { run_date_sgt: runDate, ticker, metric: 'return_20d', value: round(pct(latest, close20)), source: 'twelve_data' } },
  { json: { run_date_sgt: runDate, ticker, metric: 'ma_50', value: round(ma50), source: 'twelve_data' } },
  { json: { run_date_sgt: runDate, ticker, metric: 'ma_200', value: round(ma200), source: 'twelve_data' } },
  { json: { run_date_sgt: runDate, ticker, metric: 'price_vs_50dma_pct', value: round(pct(latest, ma50)), source: 'twelve_data' } },
  { json: { run_date_sgt: runDate, ticker, metric: 'price_vs_200dma_pct', value: round(pct(latest, ma200)), source: 'twelve_data' } },
  { json: { run_date_sgt: runDate, ticker, metric: 'drawdown_52w_pct', value: round(pct(latest, high52)), source: 'twelve_data' } }
];

const obs = $('Normalize').all().map(i => i.json);

let rawVals = [];
try {
  rawVals = $('Get Valuations').first().json;
} catch (e) {
  rawVals = [];
}

const vals = Array.isArray(rawVals) ? rawVals : [];

function getMetric(ticker, metric) {
  return obs.find(r => r.ticker === ticker && r.metric === metric)?.value;
}

function getValuation(ticker) {
  return vals.find(v => v.ticker === ticker) || {
    ticker,
    forward_pe: null,
    ev_sales: null,
    revenue_growth: null
  };
}

const tickers = [...new Set(obs.map(r => r.ticker))];
const out = [];

for (const ticker of tickers) {
  const r20 = Number(getMetric(ticker, 'return_20d'));
  const vs200 = Number(getMetric(ticker, 'price_vs_200dma_pct'));
  const drawdown = Number(getMetric(ticker, 'drawdown_52w_pct'));

  const valuationInput = getValuation(ticker);
  const forwardPe = Number(valuationInput.forward_pe);
  const evSales = Number(valuationInput.ev_sales);
  const revenueGrowth = Number(valuationInput.revenue_growth);

  let momentumScore = 50;
  if (Number.isFinite(r20)) {
    if (r20 < 0) momentumScore = 30;
    else if (r20 < 10) momentumScore = 50;
    else if (r20 < 20) momentumScore = 70;
    else momentumScore = 90;
  }

  let peScore = 60;
  if (Number.isFinite(forwardPe)) {
    if (forwardPe < 25) peScore = 30;
    else if (forwardPe < 40) peScore = 50;
    else if (forwardPe < 70) peScore = 70;
    else peScore = 90;
  }

  let salesScore = 60;
  if (Number.isFinite(evSales)) {
    if (evSales < 6) salesScore = 30;
    else if (evSales < 10) salesScore = 50;
    else if (evSales < 18) salesScore = 70;
    else salesScore = 90;
  }

  let growthOffset = 0;
  if (Number.isFinite(revenueGrowth)) {
    if (revenueGrowth > 40) growthOffset = -10;
    else if (revenueGrowth > 20) growthOffset = -5;
    else if (revenueGrowth < 5) growthOffset = 10;
  }

  const valuationScore = Math.max(
    20,
    Math.min(95, peScore * 0.55 + salesScore * 0.45 + growthOffset)
  );

  let overheatingScore = 50;
  if (Number.isFinite(vs200)) {
    if (vs200 < 0) overheatingScore = 30;
    else if (vs200 < 15) overheatingScore = 50;
    else if (vs200 < 30) overheatingScore = 70;
    else overheatingScore = 90;
  }

  if (Number.isFinite(drawdown)) {
    if (drawdown > -5) overheatingScore += 10;
    else if (drawdown < -25) overheatingScore -= 10;
  }

  overheatingScore = Math.max(20, Math.min(95, overheatingScore));

  const aiHypeScore = 50;

  const overallScore =
    momentumScore * 0.25 +
    valuationScore * 0.35 +
    overheatingScore * 0.25 +
    aiHypeScore * 0.15;

  let signalLabel = 'Normal';
  if (overallScore >= 75) signalLabel = 'Bubble Risk';
  else if (overallScore >= 60) signalLabel = 'Overheated';
  else if (overallScore >= 40) signalLabel = 'Watch';

  out.push({
    json: {
      run_date_sgt: new Date().toLocaleDateString('en-CA', {
        timeZone: 'Asia/Singapore'
      }),
      ticker,
      momentum_score: Number(momentumScore.toFixed(1)),
      valuation_score: Number(valuationScore.toFixed(1)),
      overheating_score: Number(overheatingScore.toFixed(1)),
      ai_hype_score: aiHypeScore,
      overall_ai_risk_score: Number(overallScore.toFixed(1)),
      signal_label: signalLabel,
      explanation:
        `${ticker}: ${signalLabel}. ` +
        `Overall AI risk score ${overallScore.toFixed(1)}/100. ` +
        `Momentum=${momentumScore}, Valuation=${valuationScore.toFixed(1)}, ` +
        `Overheating=${overheatingScore}, Hype=${aiHypeScore}.`
    }
  });
}

return out;
